use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn analyze_dependency_spec (dep_name : & str , dep_value : & toml :: Value , analysis : & mut DependencyAnalysis) -> String { let stats = analysis . dependency_types . entry (dep_name . to_string ()) . or_insert_with (| | DependencyTypeStats { string_deps : 0 , table_deps : 0 , workspace_deps : 0 , path_deps : 0 , version_deps : 0 , }) ; match dep_value { toml :: Value :: String (version) => { stats . string_deps += 1 ; stats . version_deps += 1 ; format ! ("version=\"{}\"" , version) } toml :: Value :: Table (table) => { stats . table_deps += 1 ; let mut spec_parts = Vec :: new () ; if table . contains_key ("workspace") { stats . workspace_deps += 1 ; spec_parts . push ("workspace=true" . to_string ()) ; } if let Some (path) = table . get ("path") { stats . path_deps += 1 ; spec_parts . push (format ! ("path=\"{}\"" , path . as_str () . unwrap_or ("?"))) ; } if let Some (version) = table . get ("version") { stats . version_deps += 1 ; spec_parts . push (format ! ("version=\"{}\"" , version . as_str () . unwrap_or ("?"))) ; } if let Some (optional) = table . get ("optional") { spec_parts . push (format ! ("optional={}" , optional . as_bool () . unwrap_or (false))) ; } if let Some (features) = table . get ("features") { spec_parts . push (format ! ("features={:?}" , features)) ; } format ! ("{{{}}}" , spec_parts . join (", ")) } _ => { format ! ("unknown: {:?}" , dep_value) } } }